    assert!(s.fct_p99_ns > 0);
}

#[test]
fn tcp_dumbell_alltoall_completes() {
    let s = run_tcp();
    assert_eq!(s.total_flows, 30);
    assert_eq!(s.completed_flows, 30, "SimpleTcp 应完成所有流");
