//! Ring AllReduce 流量模式
//!
//! 经典实现：N 个节点环形排列，每个节点持有一份大小为 M 的张量。
//! Ring AllReduce 共 2*(N-1) 步，每步每个节点发送 M/N 字节给下一个节点。
//!
//! 为简化我们生成"所有节点之间的链状流"：节点 i 在每一步向 (i+1) mod N 发 M/N 字节。

use super::FlowDesc;
use crate::EntityId;

pub struct RingAllReduce {
    pub nodes: Vec<EntityId>,
    pub message_bytes: u64,
    pub start_time_ns: u64,
}

impl RingAllReduce {
    pub fn generate(&self) -> Vec<FlowDesc> {
        let n = self.nodes.len();
        if n < 2 { return Vec::new(); }
        let chunk = self.message_bytes / n as u64;
        let steps = 2 * (n - 1);
        let mut flows = Vec::new();
        let mut fid: u32 = 0;
        for step in 0..steps {
            // 每步各节点同时发送给下一个；我们为了简化把它们的开始时间都设为 start_time_ns
            // （理想 ring 应该是 step k 的发送依赖 step k-1 的接收，这里简化）
            for i in 0..n {
                let src = self.nodes[i];
                let dst = self.nodes[(i + 1) % n];
                flows.push(FlowDesc {
                    flow_id: fid, src, dst,
                    bytes: chunk,
                    start_time_ns: self.start_time_ns + (step as u64) * 1000, // 错开 1us
                });
                fid += 1;
            }
        }
        flows
    }
}

//! AllToAll 流量：每对节点之间各发一条流

use super::FlowDesc;
use crate::EntityId;

pub struct AllToAll {
    pub nodes: Vec<EntityId>,
    pub bytes_per_pair: u64,
    pub start_time_ns: u64,
}

impl AllToAll {
    pub fn generate(&self) -> Vec<FlowDesc> {
        let mut flows = Vec::new();
        let mut fid: u32 = 0;
        for &src in &self.nodes {
            for &dst in &self.nodes {
                if src == dst { continue; }
                flows.push(FlowDesc { flow_id: fid, src, dst, bytes: self.bytes_per_pair, start_time_ns: self.start_time_ns });
                fid += 1;
            }
        }
        flows
    }
}

//! Incast 多对一流量模式

use super::FlowDesc;
use crate::EntityId;

pub struct Incast {
    pub senders: Vec<EntityId>,
    pub receiver: EntityId,
    pub bytes_per_sender: u64,
    pub start_time_ns: u64,
}

impl Incast {
    pub fn generate(&self) -> Vec<FlowDesc> {
        // flow_id 需要全局唯一（全部在仿真中可区别）
        // 这里用递增序号，从 1 开始避免 与缺省 0 冲突
        self.senders.iter().enumerate().map(|(i, &src)| FlowDesc {
            flow_id: (i + 1) as u32,
            src, dst: self.receiver,
            bytes: self.bytes_per_sender,
            start_time_ns: self.start_time_ns,
        }).collect()
    }
}

//! 混合流量生成器
//!
//! 将多种流量生成器的输出按比例混合，构造复合工作负载。
//! 典型用法：80% mice flow + 20% elephant flow，
//! 或 Incast 背景流 + AllToAll 前台流。
//!
//! 混合时自动为 flow_id 去重，保证全局唯一。

use super::FlowDesc;

/// 混合流量组件描述
#[derive(Debug, Clone)]
pub struct MixComponent {
    /// 流量描述列表（通常由其他生成器预先 `generate()` 产出）
    pub flows: Vec<FlowDesc>,
    /// 该组件在混合中的权重（仅用于参考比例，不强制截断）
    pub weight: f64,
}

/// 混合流量生成器
#[derive(Debug, Clone)]
pub struct Mix {
    pub components: Vec<MixComponent>,
}

impl Mix {
    /// 创建空的混合器
    pub fn new() -> Self {
        Self { components: Vec::new() }
    }

    /// 添加一个组件
    pub fn add(mut self, flows: Vec<FlowDesc>, weight: f64) -> Self {
        self.components.push(MixComponent { flows, weight });
        self
    }

    /// 生成混合后的流量列表
    ///
    /// 行为：
    /// - 将所有组件的流按 `weight` 降序排列（权重大的在前）
    /// - 重新分配全局唯一的 `flow_id`
    /// - 返回平铺后的 `Vec<FlowDesc>`
    pub fn generate(&self) -> Vec<FlowDesc> {
        let mut all = Vec::new();
        // 按权重降序合并（权重大的优先，模拟 foreground traffic）
        let mut comps: Vec<_> = self.components.iter().collect();
        comps.sort_by(|a, b| b.weight.partial_cmp(&a.weight).unwrap());

        let mut next_fid: u32 = 0;
        for comp in comps {
            for mut f in comp.flows.clone() {
                f.flow_id = next_fid;
                next_fid += 1;
                all.push(f);
            }
        }
        all
    }
}

