/// 拓扑的最终产物
pub struct Topology {
    /// 主机 EntityId（从 0 开始连续编号）
    pub hosts: Vec<EntityId>,
    /// 交换机 EntityId（接在主机之后编号）
    pub switches: Vec<Switch>,
    /// 全部链路
    pub links: LinkRegistry,
