}

//! 网卡模型与可插拔协议栈（阶段三重构后）
//!
//! - `protocol`: 通用 `Protocol` trait + `ProtocolStats`
//! - `strack`: STrack 协议实现（含 ECMP / STrack 两种模式）
//! - `tcp`: 简化 TCP 实现（验证 trait 通用性）

pub mod protocol;
